template:
fn get_user(id: u32) -> Option<String> {
    if id == 1 { Some(String::from("Alice")) } else { None }
}

fn fetch_name(id: u32) -> Result<String, &'static str> {
    let name = get_user(id)⟦slot1⟧⟦slot2⟧;
    Ok(name)
}

fn main() {
    println!("{:?}", fetch_name(1));
}

tests:
#[test]
fn reports_missing() {
    assert_eq!(fetch_name(2), Err("user not found"));
}
